export interface Schema<A> {
  readonly Type: A
  readonly decode: (u: unknown) => A
}
export const literals = <const A extends ReadonlyArray<string>>(...xs: A): Schema<A[number]> => ({
  Type: undefined as unknown as A[number],
  decode: (u) => (xs.includes(u as string) ? (u as A[number]) : xs[0]),
})

