import { readFileSync } from "node:fs"
import { literals } from "./lib.ts"

const Issue = literals("open", "closed")
type Item = typeof Issue.Type

/** Every issue state a sweep decodes. */
export const decodeAll = (xs: ReadonlyArray<unknown>): ReadonlyArray<string> => xs.map((x) => Issue.decode(x))

/** How many items the file at path lists. */
export const countItems = (path: string): number => {
  const items: ReadonlyArray<Item> = []
  return readFileSync(path, "utf8").split("\n").length + items.length
}

import { readFileSync } from "node:fs"
import { literals } from "./lib.ts"

const Attachment = literals("viewer", "editor")
type Attachment = typeof Attachment.Type

interface Connection {
  readonly id: string
  readonly attachment: Attachment
}

const decodeAttachment = (u: unknown): Attachment => Attachment.decode(u)

/** The role a socket's attachment decodes to. */
export const role = (u: unknown): string => decodeAttachment(u)

/** The connections the roster file at path lists. */
export const connections = (path: string): ReadonlyArray<Connection> =>
  readFileSync(path, "utf8").split("\n").map((id) => ({ id, attachment: "viewer" }))
